// Phase 5: Studio and the documentation portal, from the installed protected distribution, in a real browser.
// Every Studio view is opened; any icon that the pruned icon set cannot serve, any page error or any empty view is a failure.
//   node scripts/psd/validate/phase5-studio.mjs --label 0.1.0-alpha.1   (needs the workspace generated by phase 3)
import { existsSync, readFileSync } from "node:fs";
import { join, resolve } from "node:path";
import { spawn, spawnSync } from "node:child_process";
import { Evidence, makeIso } from "./iso.mjs";

const repo = resolve(new URL("../../..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
const a = process.argv.slice(2);
const label = a[a.indexOf("--label") + 1] ?? "0.1.0-alpha.1";
const K = join(process.env.USERPROFILE, ".pso-psd");
const evDir = join(repo, "docs", "implementation", "evidence", "psd", label);
const ev = new Evidence(join(evDir, "validation-studio.json"));
const iso = makeIso(join(K, "validation", "iso-dev"), { fresh: false });
const ver = join(iso.root, "pso", "versions", label);
const cli = join(ver, "node_modules", "@pso", "cli", "bin", "pso.js");
const ws = join(iso.work, "shop");
if (!existsSync(join(ws, "pso.workspace.json"))) { console.error("run phase 3 first (it generates the workspace)"); process.exit(2); }

const PORT = 4317;
const child = spawn(process.execPath, [cli, "studio", "--no-open", "--port", String(PORT), "--frontend-ops"], { cwd: ws, env: iso.env, stdio: ["ignore", "pipe", "pipe"], windowsHide: true });
let out = ""; child.stdout.on("data", (c) => (out += c)); child.stderr.on("data", (c) => (out += c));
const kill = () => spawnSync("taskkill", ["/PID", String(child.pid), "/T", "/F"], { windowsHide: true });
try {
  const t0 = Date.now(); let url;
  while (Date.now() - t0 < 60_000 && !(url = /(http:\/\/127\.0\.0\.1:\d+\/\?t=[0-9A-Za-z_-]+)/.exec(out)?.[1])) await new Promise((r) => setTimeout(r, 500));
  ev.check("pso studio starts and prints a tokenised loopback URL", !!url, out.slice(-200));
  if (!url) throw new Error("no studio url");
  const base = `http://127.0.0.1:${PORT}`;
  const bare = await fetch(`${base}/api/overview`).then((r) => r.status);
  ev.check("without the startup token the API is refused (403)", bare === 403, String(bare));

  const { chromium } = await import("file:///" + join(repo, "node_modules", "playwright-core", "index.mjs").replace(/\\/g, "/"));
  const browser = await chromium.launch({ channel: "chrome", headless: true });
  const errors = [], missing = [], consoleErrors = [];
  try {
    const page = await (await browser.newContext({ viewport: { width: 1360, height: 860 } })).newPage();
    page.on("pageerror", (e) => errors.push(String(e.message).slice(0, 160)));
    page.on("console", (m) => { if (m.type() === "error" && !/favicon/.test(m.text())) consoleErrors.push(m.text().slice(0, 160)); });
    page.on("response", (r) => { if (r.status() >= 400 && !/favicon/.test(r.url())) missing.push(`${r.status()} ${r.url().replace(base, "")}`); });
    await page.goto(url, { waitUntil: "networkidle", timeout: 60_000 });
    const shell = await page.waitForSelector(".nav-item", { timeout: 30_000 }).then(() => true, () => false);
    if (!shell) { ev.check("Studio shell renders with its navigation", false, `url ${page.url().replace(base, "")} | page errors: ${errors.join(" | ")} | console: ${consoleErrors.join(" | ")} | failed: ${[...new Set(missing)].join(" | ")} | body: ${(await page.locator("body").innerText().catch(() => "")).slice(0, 200).replace(/\s+/g, " ")}`); throw new Error("studio shell did not render"); }
    const ids = await page.$$eval(".nav-item", (els) => els.map((e) => e.getAttribute("data-id")));
    ev.check("Studio shell renders with its navigation", ids.length >= 8, ids.join(","));
    const empty = [];
    for (const id of ids) {
      await page.goto(`${base}/#/${id}`, { waitUntil: "networkidle", timeout: 60_000 }).catch(() => {});
      await page.waitForTimeout(900);
      const len = (await page.locator("#main, main").first().innerText({ timeout: 10_000 }).catch(() => "")).trim().length;
      if (len < 20) empty.push(`${id}:${len}`);
    }
    ev.check(`every Studio view renders content (${ids.length} views)`, empty.length === 0, empty.join(", "));
    ev.check("no icon or asset is missing: the pruned icon set serves every Studio view (no 404s)", missing.length === 0, [...new Set(missing)].slice(0, 6).join(" | "));
    ev.check("no uncaught page errors and no console errors across all views", errors.length === 0 && consoleErrors.length === 0, [...errors, ...consoleErrors].slice(0, 3).join(" | "));
    const api = async (p) => page.evaluate(async (u) => { const r = await fetch(u); return { status: r.status, body: await r.json() }; }, `${base}${p}`);
    const ov = await api("/api/overview");
    ev.check("Studio API: overview lists the generated services (structural discovery through the protected CLI)", ov.status === 200 && JSON.stringify(ov.body).includes("catalog") && JSON.stringify(ov.body).includes("gateway"), JSON.stringify(ov.body).slice(0, 120));
    const rt = await api("/api/routes");
    ev.check("Studio API: routes include the declared /customers and /orders", rt.status === 200 && JSON.stringify(rt.body).includes("/customers") && JSON.stringify(rt.body).includes("/orders"));
    // the documentation portal built on demand and served by Studio
    const docs = await page.goto(`${base}/docs/`, { waitUntil: "networkidle", timeout: 120_000 });
    const title = await page.title();
    ev.check("the documentation portal renders (built from the installed docs, icons from the pruned set)", docs?.status() === 200 && /PSO/i.test(title), `${docs?.status()} "${title}"`);
    const docsPage = await page.goto(`${base}/docs/getting-started/quick-start.html`, { waitUntil: "networkidle", timeout: 60_000 });
    ev.check("a documentation page renders with its code blocks and the sprite icons", docsPage?.status() === 200 && (await page.locator("pre code, pre").count()) > 0 && (await page.locator("svg use").count()) > 0);
    ev.check("the portal produced no new missing assets", missing.length === 0, [...new Set(missing)].slice(0, 4).join(" | "));
    await page.screenshot({ path: join(evDir, "docs-portal.png") });
  } finally { await browser.close(); }
} catch (e) { ev.check("phase 5 completed without an unexpected error", false, e.message); }
finally { kill(); }
ev.save({ label });
console.log(`\n${ev.checks.length - ev.failed}/${ev.checks.length} checks passed`);
process.exit(ev.failed ? 1 : 0);
